beforeSaveCustomScript:
ifThen(!connectedHrs, connectedHrs = 0);
remainingHrs = totalHrs - connectedHrs;
ifThen(entity\isAttributeChanged('connectedHrs') && totalHrs > 0 && remainingHrs <= 0, status = 'Completed');
ifThen(entity\isAttributeChanged('connectedHrs') && remainingHrs > 0 && status == 'Completed', status = 'Active');
ifThen(!assignedUserId && projectId, assignedUserId = record\attribute('CProject', projectId, 'assignedUserId'));
ifThen(paymentStatus == 'Paid' && !paidDate, paidDate = datetime\today());
$d = ifThenElse(startDate, startDate, datetime\today());
name = string\concatenate(record\attribute('CProject', projectId, 'name'), ' - ', datetime\format($d, 'Asia/Kolkata', 'DD MMM YYYY'));
